def main():
    N, A, B = map(int, input().split())
    str = list(input())

    balance = 0
    min_balance = 0

    for char in str:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        min_balance = min(min_balance, balance)

    imbalance = abs(min_balance)

    if imbalance == 0:
        result = 0
    else:
        if imbalance % 2 == 0:
            result = min(B * imbalance, A * (imbalance // 2))
        else:
            result = min(B * (imbalance + 1), A * ((imbalance // 2) + 1))

    print(result)
